from rich.console import Console
import io

def test_regular_object():
    console = Console(file=io.StringIO(), force_jupyter=True)
    class Thing:
        def __repr__(self):
            return "hello"
    result = _ipy_display_hook(Thing(), console=console)
    print(f"Result: {repr(result)}")
    assert result == "hello"

if __name__ == "__main__":
    test_regular_object()

